"""Ediciones reales y eliminación de un paso DESARROLLO nuevo, sin tocar registros ajenos."""
import json,unittest,base64,urllib.request,uuid
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
class EdicionesClinica(unittest.TestCase):
 def test_ediciones_y_paso_terminal(self):
  a=json.loads(Path('/Users/albertoalexanderitzepsarceno/Library/Application Support/GalenosSV/credentials.json').read_text())['administrador-local'];auth='Basic '+base64.b64encode((a['username']+':'+a['password']).encode()).decode()
  def get(path):
   with urllib.request.urlopen(urllib.request.Request('http://localhost:9080/GalenosSV/resources/v2/'+path,headers={'Authorization':auth}))as r:return json.load(r)
  proc=next(p for p in get('procedimiento?max=100') if p['nombre'].startswith('DESARROLLO procedimiento flujo') and p['activo']);steps=get('procedimiento_paso?idProcedimiento='+proc['idProcedimiento']);first=next(s for s in steps if s['nombre']=='Inicio Desarrollo');clinic=get('clinica_disponible')[0]['idClinica'];consulta=next(c for c in get('consulta?idClinica='+clinic+'&max=100') if(c['referenciaExterna']or'').startswith('DESARROLLO-'))
  with sync_playwright()as p:
   b=p.chromium.launch(headless=True);page=b.new_page(viewport={'width':1440,'height':1100});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://localhost:3000/#procedimiento');page.locator('#gestion-usuario').fill(a['username']);page.locator('#gestion-clave').fill(a['password']);page.get_by_role('button',name='Iniciar sesión',exact=True).click();expect(page.locator('[data-catalogos] .gestion-tools').first).to_be_visible();page.locator('[data-catalogos] input[type=search]').fill(proc['nombre']);page.get_by_role('button',name='Buscar',exact=True).click();page.locator('[data-catalogos] tbody tr').filter(has_text=proc['nombre']).get_by_role('button',name='Gestionar pasos',exact=True).click()
   line=page.locator('#gestion .gestion-tools:visible').filter(has_text='Inicio Desarrollo');line.get_by_role('button',name='Editar',exact=True).click();d=page.locator('#gestion dialog:visible');d.locator('[name=nombre]').fill('Inicio Desarrollo Editado');d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible();self.assertEqual(get('procedimiento_paso/'+first['idProcedimientoPaso'])['nombre'],'Inicio Desarrollo Editado');line.get_by_role('button',name='Editar',exact=True).click();d.locator('[name=nombre]').fill('Inicio Desarrollo');d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible()
   token=uuid.uuid4().hex[:8];name='DESARROLLO paso descartable '+token;page.get_by_role('button',name='Nuevo paso',exact=True).click();d=page.locator('#gestion dialog:visible');d.locator('[name=nombre]').fill(name);expect(d.locator('[name=idPasoOrigen] option').nth(1)).to_be_attached();d.locator('[name=idPasoOrigen]').select_option(first['idProcedimientoPaso']);d.locator('[name=idRol]').select_option(first['idRol']);d.locator('[name=tipoSecuencia]').select_option('ALTERNATIVA');d.locator('[name=indicaFin]').check();d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible();line=page.locator('#gestion .gestion-tools:visible').filter(has_text=name);expect(line).to_have_count(1);page.once('dialog',lambda x:x.accept());line.get_by_role('button',name='Eliminar paso terminal',exact=True).click();expect(line).to_have_count(0);self.assertFalse(any(s['nombre']==name for s in get('procedimiento_paso?idProcedimiento='+proc['idProcedimiento'])))
   page.locator('[data-navigation] a[href="#main"]').click();page.locator('#clinica').select_option(clinic);expect(page.locator('tarjeta-consulta').first).to_be_visible();cards=page.locator('tarjeta-consulta');card=next(cards.nth(i) for i in range(cards.count()) if cards.nth(i).evaluate('(c)=>c.consulta.idConsulta')==consulta['idConsulta']);card.locator('button').click();state=get('consulta_procedimiento_paso?idClinica='+clinic+'&idConsulta='+consulta['idConsulta'])[0]['estado'];expect(page.locator('.consulta-relaciones')).to_contain_text(state);line=page.locator('.consulta-relaciones .gestion-tools').filter(has_text=state).first;line.get_by_role('button',name='Editar',exact=True).click();d=page.locator('[data-consulta-gestion] dialog');d.locator('[name=estado]').select_option('EN_CURSO');d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible();line=page.locator('.consulta-relaciones .gestion-tools').filter(has_text='EN_CURSO').first;line.get_by_role('button',name='Órdenes',exact=True).click();root=page.locator('[data-ordenes]');expect(root).to_contain_text('DESARROLLO orden');root.get_by_role('button',name='Editar',exact=True).first.click();d=root.locator('dialog');d.locator('[name=indicaciones]').fill('DESARROLLO orden editada '+token);d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible();expect(root).to_contain_text('DESARROLLO orden editada '+token);root.get_by_role('button',name='Resultados',exact=True).first.click();root.get_by_role('button',name='Editar',exact=True).first.click();d.locator('[name=resultado]').fill('DESARROLLO resultado editado '+token);d.get_by_role('button',name='Guardar',exact=True).click();expect(d).not_to_be_visible();expect(root).to_contain_text('DESARROLLO resultado editado '+token);self.assertEqual(errors,[]);b.close()
if __name__=='__main__':unittest.main(verbosity=2)
